import express from "express";
import path from "path";
import multer from "multer";
import cors from "cors";
import { createServer as createViteServer } from "vite";
import fs from "fs";

// Simple JSON file based DB for demonstration
const DB_FILE = path.join(process.cwd(), "db.json");
const UPLOAD_DIR = path.join(process.cwd(), "uploads");

if (!fs.existsSync(UPLOAD_DIR)) {
  fs.mkdirSync(UPLOAD_DIR, { recursive: true });
}

function readDb() {
  if (!fs.existsSync(DB_FILE)) {
    return {
      news: [],
      services: [],
      team: [],
      settings: {
        phones: "+962 (0)6 4129494",
        email: "info@elitefalconslogistics.com",
        address: "Al Harrana Building 150, Mecca Street, 2nd Floor – Office 201, Amman – Jordan"
      }
    };
  }
  return JSON.parse(fs.readFileSync(DB_FILE, "utf-8"));
}

function writeDb(data: any) {
  fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));
}

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(cors());
  app.use(express.json());
  app.use(express.static("public"));
  
  // Serve uploaded files securely
  app.use("/uploads", express.static(UPLOAD_DIR));

  const upload = multer({ dest: UPLOAD_DIR });

  // --- API Routes ---
  
  app.get("/api/health", (req, res) => {
    res.json({ status: "ok" });
  });

  // CMS: Get Settings
  app.get("/api/settings", (req, res) => {
    const db = readDb();
    res.json(db.settings);
  });

  // CMS: Update Settings
  app.post("/api/settings", (req, res) => {
    const db = readDb();
    db.settings = { ...db.settings, ...req.body };
    writeDb(db);
    res.json({ success: true, settings: db.settings });
  });

  // CMS: File Upload
  app.post("/api/upload", upload.single("file"), (req, res) => {
    if (!req.file) {
       res.status(400).json({ error: "No file uploaded" });
       return;
    }
    res.json({ url: `/uploads/${req.file.filename}` });
  });

  // CMS: News CRUD
  app.get("/api/news", (req, res) => {
    const db = readDb();
    res.json(db.news);
  });
  
  app.post("/api/news", (req, res) => {
    const db = readDb();
    const item = { id: Date.now().toString(), ...req.body, createdAt: new Date() };
    db.news.push(item);
    writeDb(db);
    res.json(item);
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*all', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
